import type { ValueStepperProps, ExtendedStepperProps } from "./value-stepper.types";

import { Add as AddIcon, Subtract as SubtractIcon } from "@exp-textura/icons";
import React, {
  forwardRef,
  useState,
  useEffect,
  useCallback,
  useRef,
  Children,
  isValidElement,
  cloneElement,
} from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import { Input } from "@components/input";
import { IconButton } from "@components/icon-button";

import { ValueStepperClasses, StyledValueStepper } from "./value-stepper.styles";

const getValueStepperValidChildren = (children: React.ReactNode) => {
  return Children.toArray(children).filter((child) => {
    if (!isValidElement<ExtendedStepperProps>(child)) {
      return false;
    }

    const childType = child.type as typeof Increment | typeof Decrement | typeof InputField;
    const childDisplayName = childType.displayName;

    if (
      childDisplayName !== "ValueStepper.Increment" &&
      childDisplayName !== "ValueStepper.Decrement" &&
      childDisplayName !== "ValueStepper.Input"
    ) {
      return false;
    }
    return true;
  }) as React.ReactElement<ExtendedStepperProps>[];
};

const ValueStepperRoot = forwardRef<HTMLDivElement, ValueStepperProps>(
  (
    {
      className,
      variant = "default",
      value,
      defaultValue,
      minvalue,
      maxvalue,
      step = 1,
      disabled = false,
      onValueChange,
      name,
      children,
      "aria-required": ariaRequired,
      "aria-invalid": ariaInvalid,
      "aria-describedby": ariaDescribedby,
      id,
      size = "default",
      ...props
    },
    ref,
  ) => {
    const theme = useTheme();
    const [changedValue, setChangedValue] = useState(defaultValue || 0);
    const currentValue = value ?? changedValue;

    const handleChange = (newVal: number) => {
      let updatedValue = newVal;
      if (minvalue !== undefined) {
        updatedValue = Math.max(updatedValue, minvalue);
      }
      if (maxvalue !== undefined) {
        updatedValue = Math.min(updatedValue, maxvalue);
      }

      if (value === undefined) setChangedValue(updatedValue);
      onValueChange?.(updatedValue);
    };

    const validChildren = getValueStepperValidChildren(children);

    return (
      <StyledValueStepper
        ref={ref}
        className={clsx(ValueStepperClasses.root, className, {
          [ValueStepperClasses.sm]: size === "sm",
        })}
        currentTheme={theme}
        name={name}
        variant={variant}
        {...props}
      >
        {Children.map(validChildren, (child) =>
          cloneElement(child, {
            value: currentValue,
            minvalue,
            maxvalue,
            step,
            disabled,
            handleChange,
            size,
            "aria-required": ariaRequired,
            "aria-invalid": ariaInvalid,
            "aria-describedby": ariaDescribedby,
            id,
          }),
        )}
      </StyledValueStepper>
    );
  },
);
ValueStepperRoot.displayName = "ValueStepper";

const ActionButton = forwardRef<HTMLButtonElement, ExtendedStepperProps>(
  (
    {
      value = 0,
      minvalue = Number.MIN_SAFE_INTEGER,
      maxvalue = Number.MAX_SAFE_INTEGER,
      step = 1,
      disabled,
      handleChange,
      isIncrement,
      children,
      className,
      ...props
    },
    ref,
  ) => {
    const isDisabled = isIncrement ? value >= maxvalue : value <= minvalue;
    const buttonProps = {
      "aria-label": isIncrement ? "Increment value" : "Decrement value",
      onClick: () => !disabled && handleChange?.(value + (isIncrement ? step : -step)),
    };

    if (isValidElement(children)) {
      return cloneElement(children, { ...buttonProps });
    }

    return (
      <IconButton
        ref={ref}
        buttonType="secondary"
        className={clsx(className)}
        disabled={isDisabled || disabled}
        {...buttonProps}
        {...props}
        size="sm"
      >
        {isIncrement ? <AddIcon /> : <SubtractIcon />}
      </IconButton>
    );
  },
);

const Increment = forwardRef<HTMLButtonElement, ExtendedStepperProps>((props, ref) => (
  <ActionButton {...props} ref={ref} isIncrement className={ValueStepperClasses.increment} />
));
Increment.displayName = "ValueStepper.Increment";

const Decrement = forwardRef<HTMLButtonElement, ExtendedStepperProps>((props, ref) => (
  <ActionButton
    {...props}
    ref={ref}
    className={ValueStepperClasses.decrement}
    isIncrement={false}
  />
));
Decrement.displayName = "ValueStepper.Decrement";

const InputField = forwardRef<HTMLInputElement, ExtendedStepperProps>(
  ({ value = 0, disabled, handleChange, defaultValue, size, ...props }, ref) => {
    const [localValue, setLocalValue] = useState(String(value));
    const isEditingRef = useRef(false);

    // Sync external value → local display when not actively editing
    useEffect(() => {
      if (!isEditingRef.current) {
        setLocalValue(String(value));
      }
    }, [value]);

    const commitValue = useCallback(() => {
      isEditingRef.current = false;
      const parsed = Number(localValue);
      if (localValue !== "" && !isNaN(parsed)) {
        handleChange?.(parsed);
      } else {
        // Reset to last valid value if input is invalid
        setLocalValue(String(value));
      }
    }, [localValue, handleChange, value]);

    return (
      <div className={ValueStepperClasses.input}>
        <Input
          ref={ref}
          defaultValue={defaultValue}
          disabled={disabled}
          inputSize={size}
          type="number"
          value={localValue}
          onBlur={commitValue}
          onChange={(e: React.ChangeEvent<HTMLInputElement>) => {
            setLocalValue(e.target.value);
          }}
          onFocus={() => {
            isEditingRef.current = true;
          }}
          onKeyDown={(e: React.KeyboardEvent<HTMLInputElement>) => {
            if (e.key === "Enter") {
              commitValue();
              (e.target as HTMLInputElement).blur();
            }
          }}
          {...props}
        />
      </div>
    );
  },
);
InputField.displayName = "ValueStepper.Input";

type ValueStepperCompoundComponent = typeof ValueStepperRoot & {
  Increment: typeof Increment;
  Decrement: typeof Decrement;
  Input: typeof InputField;
};

const ValueStepper = ValueStepperRoot as ValueStepperCompoundComponent;
ValueStepper.Increment = Increment;
ValueStepper.Decrement = Decrement;
ValueStepper.Input = InputField;

export default ValueStepper;
